package net.yut.exsanguinate.util;

import net.minecraft.item.Item;
import net.minecraft.registry.RegistryKeys;
import net.minecraft.registry.tag.TagKey;
import net.minecraft.util.Identifier;
import net.yut.exsanguinate.Exsanguinate;

/**
 * TAGS - what and why:
 *
 * A tag is a named group of things (items, blocks, ...). Instead of checking
 * "is this item exactly the Carnelian Oath?", you can check "is it in the
 * exsanguinate:blades tag?" - and a tag can contain any number of items,
 * from this mod or vanilla.
 *
 * The tag JSON file is generated by ModItemTagProvider (./gradlew runDatagen).
 */
public class ModTags {
    public static class Items {

        // Our own tag: every item we consider a "blade".
        public static final TagKey<Item> BLADES = createTag("blades");

        // Helper that builds a tag key with the mod's namespace.
        private static TagKey<Item> createTag(String name) {
            return TagKey.of(RegistryKeys.ITEM, Identifier.of(Exsanguinate.MOD_ID, name));
        }
    }
}